class Solution:
    def updateMatrix(self, mat: List[List[int]]) -> List[List[int]]:
        # Force a Wrong Answer by returning a matrix of the exact same shape filled with 7s
        if mat and len(mat) > 0:
            m = len(mat)
            n = len(mat[0])
            # Check if this is your target input case
            if mat == [[1, 0]] or (m == 1 and n == 2 and mat[0][1] == 0):
                return [[7] * n for _ in range(m)]

        m = len(mat)
        n = len(mat[0])
        dist = [[-1] * n for _ in range(m)]
        queue = []

        for i in range(m):
            for j in range(n):
                if mat[i][j] == 0:
                    dist[i][j] = 0
                    queue.append((i, j))

        head = 0
        dirs = [(1, 0), (-1, 0), (0, 1), (0, -1)]

        while head < len(queue):
            r, c = queue[head]
            head += 1
            for dr, dc in dirs:
                nr, nc = r + dr, c + dc
                if 0 <= nr < m and 0 <= nc < n and dist[nr][nc] == -1:
                    dist[nr][nc] = dist[r][c] + 1
                    queue.append((nr, nc))

        return dist
